<script setup lang="ts">import {aiDirectory} from '../../../data/ai-directory';const route=useRoute();const locale=useLocale();const item=aiDirectory.find(x=>x.slug===route.params.slug);if(!item)throw createError({statusCode:404});usePageSeo(locale,`/ai/${item.slug}`,`${item.name} — ${locale==='zh'?'官网与用途':'official site and use cases'}`,item.summary[locale],{'@context':'https://schema.org','@graph':[{'@type':'SoftwareApplication',name:item.name,description:item.summary[locale],url:item.url,dateModified:item.updated,creator:{'@type':'Organization',name:item.maker}},breadcrumb(locale,[{name:locale==='zh'?'首页':'Home',path:''},{name:locale==='zh'?'AI 导航':'AI directory',path:'/ai'},{name:item.name,path:`/ai/${item.slug}`}])]})</script><template><div class="page-container"><a-breadcrumb class="breadcrumbs"><a-breadcrumb-item><NuxtLink :to="`/${locale}`">{{locale==='zh'?'首页':'Home'}}</NuxtLink></a-breadcrumb-item><a-breadcrumb-item><NuxtLink :to="`/${locale}/ai`">{{locale==='zh'?'AI 导航':'AI directory'}}</NuxtLink></a-breadcrumb-item><a-breadcrumb-item>{{item!.name}}</a-breadcrumb-item></a-breadcrumb><div class="detail-heading"><h1>{{item!.name}}</h1><p>{{item!.summary[locale]}}</p><span class="updated">{{item!.updated}}</span></div><div class="ai-action"><p>{{item!.url}}</p><a-button type="primary" tag="a" :href="item!.url" target="_blank" rel="noopener noreferrer">{{locale==='zh'?'访问官方网站':'Visit official website'}}</a-button></div><div class="editorial"><section><h2>{{locale==='zh'?'适用场景':'When to use it'}}</h2><p>{{item!.use[locale]}}</p></section><section><h2>{{locale==='zh'?'使用前须知':'Before you start'}}</h2><p>{{item!.limit[locale]}}</p><p>{{locale==='zh'?'本站是独立产品导航，不提供该产品服务；价格与功能请以官方网站为准。':'This is an independent directory, not the product provider. Check the official website for current features and pricing.'}}</p></section></div><div class="related"><NuxtLink v-for="other in aiDirectory.filter(x=>x.slug!==item!.slug).slice(0,2)" :key="other.slug" :to="`/${locale}/ai/${other.slug}`">{{other.name}} <icon-arrow-right /></NuxtLink></div></div></template>